// Fit — everything the apex knows about it: origin, gateway allowlist, route, Apps-section
// entry (web-app-suite.md F4). Generated by scripts/new-web-app.sh; adding this file IS the
// registration (`registry/index.ts` globs `apps/*.ts`).
import type { ProxyMethodAllowlist } from '@tenshu/sdk/bridge'
import { appOrigin, SESSION_METHODS, type AppGlance, type HostedApp } from '../types'
import { browserZone, civilDate } from '../glanceTime'

declare global {
  interface ImportMetaEnv {
    /** The Fit app's origin (see `apps/registry/apps/fit.ts`). */
    readonly VITE_FIT_ORIGIN?: string
  }
}

// ⚠⚠ F5 — exactly the methods `web/fit` calls: its `ProxyMethod` table in
// `web/fit/src/lib/proxy.ts` (`gatewayPermissions.test.ts` fails on drift either way). Exact
// names only; a `.*` prefix only for a namespace this app owns outright, and never a bare `'*'`.
// ⚠ Not allowed, on purpose: `mapRegion.regionsIn` / `mapRegion.catalog` (a route map asks only which
// region covers a point and reads its bytes), and every native-only Fit surface (recording, Takeout,
// auto-import, onboarding — fit-app.md §Web scope → Decided), which has no gateway method anyway.
const METHODS: ProxyMethodAllowlist = [
  ...SESSION_METHODS,
  // Dashboard
  'fit.dailyAggregates',
  'fit.dailyAggregates.observe',
  // History and detail
  'fit.workoutsPage',
  'fit.workouts.changes',
  'fit.workout',
  'fit.deleteWorkout',
  'fit.importActivityFile',
  // Goals and profile
  'fit.goals',
  'fit.goals.observe',
  'fit.setGoals',
  'fit.profile',
  'fit.profile.observe',
  'fit.setUnits',
  'fit.setName',
  'fit.setBirthDate',
  'fit.setSex',
  'fit.recordHeight',
  'fit.recordWeight',
  // Data sources (read-only)
  'fit.dataSources',
  'fit.dataSources.observe',
  // The workout route map (`@tenshu/map-kit`)
  'mapRegion.regionAt',
  'mapRegion.streamRange',
]

const PROD_ORIGIN = 'https://fit.tenshu.app'

// The overview card (web-apex-home.md §3.6): today's steps against the goal, and the last workout.
// All three methods are on METHODS above. ⚠ Today's figure is the card; the goal and the last workout
// are garnish — their failure drops the bar or the line, not the card. Steps 0 is a real value.
const glance: AppGlance = {
  size: 'narrow',
  subtitle: 'today',
  async load(call) {
    const zone = browserZone()
    const today = civilDate(new Date())
    const [days, goals, workouts] = await Promise.all([
      call('fit.dailyAggregates', { from: today, to: today, zone }) as Promise<FitOk<{ days: readonly { steps: number }[] }>>,
      (call('fit.goals') as Promise<FitOk<{ goals: { steps: number } }>>).catch(() => null),
      (
        call('fit.workoutsPage', { cursor: null, pageSize: 1, zone }) as Promise<
          FitOk<{ workouts: readonly { title: string; activityType: string; startLocal: string }[] }>
        >
      ).catch(() => null),
    ])
    if (!days.ok) throw new Error(days.error.kind)
    const steps = days.days[0]?.steps ?? 0
    const goal = goals !== null && goals.ok ? goals.goals.steps : 0
    const last = workouts !== null && workouts.ok ? workouts.workouts[0] : undefined
    return {
      layout: 'stat',
      value: steps,
      unit: 'steps',
      progress: goal > 0 ? Math.min(1, steps / goal) : null,
      footnote:
        last === undefined
          ? null
          : {
              // A stored title is the user's; without one the apex words the activity type.
              title: last.title,
              titleKey: last.title === '' ? activityKey(last.activityType) : '',
              startLocal: last.startLocal.slice(0, 16),
              allDay: false,
              detail: '',
            },
    }
  },
}

const ACTIVITY_TYPES = ['running', 'walking', 'cycling', 'strength'] as const
function activityKey(activityType: string): string {
  const key = activityType.toLowerCase()
  return (ACTIVITY_TYPES as readonly string[]).includes(key) ? `activity.${key}` : 'activity.other'
}

type FitOk<T> = ({ readonly ok: true } & T) | { readonly ok: false; readonly error: { readonly kind: string } }

export const fit: HostedApp = {
  id: 'fit',
  order: 40,
  title: 'Fit',
  prodOrigin: PROD_ORIGIN,
  envName: 'VITE_FIT_ORIGIN',
  devPort: 5180,
  origin: () => appOrigin(import.meta.env.VITE_FIT_ORIGIN, PROD_ORIGIN, 5180),
  methods: METHODS,
  routePath: 'fit/*',
  sections: ['', 'history', 'profile'],
  glance,
  // ⚠ DISPLAY data for the Apps section — what the app can actually call is `methods` above.
  manifest: {
    id: 'fit',
    label: 'Fit',
    description: 'Your activity, end-to-end encrypted.',
    version: '0.1.0',
    launchPath: '/fit',
    // ⚠ The permissions listed here are DISPLAY data — what the app can actually call is `methods`.
    permissions: [
      {
        id: 'fit.read',
        label: 'Read your activity',
        description: 'See your daily activity, workouts, goals, profile and data sources.',
        state: 'granted',
        lastUsedAtMs: null,
      },
      {
        id: 'fit.write',
        label: 'Manage your workouts and settings',
        description: 'Import GPX and TCX files, delete workouts, and change your goals, profile and units.',
        state: 'granted',
        lastUsedAtMs: null,
      },
    ],
    services: [
      {
        id: 'health',
        label: 'HealthService',
        reason: 'Stores your workouts and daily activity, encrypted client-side.',
      },
      {
        id: 'preference',
        label: 'PreferenceService',
        reason: 'Stores your goals, profile and units.',
      },
      {
        id: 'mapRegion',
        label: 'MapRegionService',
        reason: 'Reads map regions to draw a workout route. Read only.',
      },
    ],
  },
}

export default fit
